#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    int k, t;
    cin >> a >> b >> k >> t;

    vector<ll> dp(1, 1);

    for (int round = 1; round <= t; ++round) {
        int previousLimit = k * (round - 1);
        int currentLimit = k * round;

        vector<ll> prefix(dp.size() + 1, 0);
        for (size_t i = 0; i < dp.size(); ++i)
            prefix[i + 1] = (prefix[i] + dp[i]) % MOD;

        vector<ll> next(2 * currentLimit + 1, 0);

        for (int sum = -currentLimit; sum <= currentLimit; ++sum) {
            int left = max(-previousLimit, sum - k);
            int right = min(previousLimit, sum + k);

            int leftIndex = left + previousLimit;
            int rightIndex = right + previousLimit;

            next[sum + currentLimit] =
                (prefix[rightIndex + 1] - prefix[leftIndex] + MOD) % MOD;
        }

        dp.swap(next);
    }

    const int limit = k * t;
    vector<ll> prefix(dp.size() + 1, 0);
    for (size_t i = 0; i < dp.size(); ++i)
        prefix[i + 1] = (prefix[i] + dp[i]) % MOD;

    ll answer = 0;

    for (int x = -limit; x <= limit; ++x) {
        ll maximumY = a + x - b - 1;
        ll countY;

        if (maximumY < -limit) {
            countY = 0;
        } else if (maximumY >= limit) {
            countY = prefix.back();
        } else {
            countY = prefix[static_cast<int>(maximumY) + limit + 1];
        }

        answer = (answer + dp[x + limit] * countY) % MOD;
    }

    cout << answer;
    return 0;
}

