#include <iostream>
#include <vector>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    int k, t;
    cin >> a >> b >> k >> t;

    const int range = k * t;
    const int offset = range;

    vector<ll> dp(2 * range + 1, 0), next(2 * range + 1, 0);
    dp[offset] = 1;

    int oldRange = 0;
    for (int step = 1; step <= t; ++step) {
        int newRange = step * k;
        ll window = 0;

        for (int sum = -newRange; sum <= newRange; ++sum) {
            int add = sum + k;
            if (add >= -oldRange && add <= oldRange) {
                window += dp[offset + add];
                if (window >= MOD) window -= MOD;
            }

            int remove = sum - k - 1;
            if (remove >= -oldRange && remove <= oldRange) {
                window -= dp[offset + remove];
                if (window < 0) window += MOD;
            }

            next[offset + sum] = window;
        }

        dp.swap(next);
        fill(next.begin(), next.end(), 0);
        oldRange = newRange;
    }

    vector<ll> prefix(2 * range + 1);
    for (int i = 0; i <= 2 * range; ++i) {
        prefix[i] = dp[i];
        if (i > 0) {
            prefix[i] += prefix[i - 1];
            if (prefix[i] >= MOD) prefix[i] -= MOD;
        }
    }

    ll answer = 0;
    for (int x = -range; x <= range; ++x) {
        __int128 limit = static_cast<__int128>(a) + x - b - 1;
        ll validY = 0;

        if (limit >= range) {
            validY = prefix.back();
        } else if (limit >= -range) {
            validY = prefix[offset + static_cast<int>(limit)];
        }

        answer = (answer + dp[offset + x] * validY) % MOD;
    }

    cout << answer;
    return 0;
}

