#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

const int64 MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, k, t;
    cin >> a >> b >> k >> t;

    vector<int64> dp(1, 1);
    int64 radius = 0;

    for (int64 step = 0; step < t; ++step) {
        vector<int64> prefix(dp.size() + 1, 0);
        for (size_t i = 0; i < dp.size(); ++i)
            prefix[i + 1] = (prefix[i] + dp[i]) % MOD;

        int64 newRadius = radius + k;
        vector<int64> next(static_cast<size_t>(2 * newRadius + 1), 0);

        for (int64 sum = -newRadius; sum <= newRadius; ++sum) {
            int64 left = max(-radius, sum - k);
            int64 right = min(radius, sum + k);

            int64 value = prefix[static_cast<size_t>(right + radius + 1)]
                        - prefix[static_cast<size_t>(left + radius)];
            if (value < 0) value += MOD;

            next[static_cast<size_t>(sum + newRadius)] = value;
        }

        dp.swap(next);
        radius = newRadius;
    }

    vector<int64> prefix(dp.size() + 1, 0);
    for (size_t i = 0; i < dp.size(); ++i)
        prefix[i + 1] = (prefix[i] + dp[i]) % MOD;

    int64 answer = 0;

    for (int64 x = -radius; x <= radius; ++x) {
        i128 limit = static_cast<i128>(x) + a - b - 1;
        int64 waysForB = 0;

        if (limit >= radius) {
            waysForB = prefix.back();
        } else if (limit >= -radius) {
            size_t count = static_cast<size_t>(limit + radius + 1);
            waysForB = prefix[count];
        }

        answer = (answer +
                  dp[static_cast<size_t>(x + radius)] * waysForB) % MOD;
    }

    cout << answer;
    return 0;
}

